use vstd::prelude::*;

verus! {
    /// bmat concatenates four equally‐sized vectors of floats in the order
    /// top_left, top_right, bottom_left, bottom_right.
    fn bmat(
        top_left: Vec<f32>,
        top_right: Vec<f32>,
        bottom_left: Vec<f32>,
        bottom_right: Vec<f32>,
    ) -> (result: Vec<f32>)
        // all four rows must have the same length
        requires
            top_right.len() == top_left.len(),
            bottom_left.len() == top_left.len(),
            bottom_right.len() == top_left.len(),
        // the result has length 4 * n
        ensures
            result.len() == 4 * top_left.len(),
        // and in ghost land it's exactly the concatenation of the four inputs
        ensures
            result@ == top_left@ + top_right@ + bottom_left@ + bottom_right@,
    {
        let n = top_left.len();
        let mut result = Vec::with_capacity(n * 4);
        result.extend(top_left);
        result.extend(top_right);
        result.extend(bottom_left);
        result.extend(bottom_right);
        result
    }
}

